            lista_finalizados.bind('<Double-Button-1>', lambda e: selecionar_finalizado())
            
            # Centralizar janela na tela
            janela_todos.update_idletasks()
            x = (janela_todos.winfo_screenwidth() // 2) - (janela_todos.winfo_width() // 2)
