    def excluir_fornecedor_permanente(self, cnpj_cpf, nome):
        """
        Remove PERMANENTEMENTE fornecedor da planilha
        
        ⚠️ ATENÇÃO: Esta ação é IRREVERSÍVEL!
        
        Args:
            cnpj_cpf: CNPJ/CPF do fornecedor (apenas números)
            nome: Nome do fornecedor (para log)
        
        Returns:
            bool: True se excluído com sucesso, False caso contrário
        """
        try:
            from src.config.config import ARQUIVO_FORNECEDORES
            from openpyxl import load_workbook
            import logging
            
            logger = logging.getLogger(__name__)
            
            wb = load_workbook(ARQUIVO_FORNECEDORES)
            ws = wb['Fornecedores']
            
            # Buscar fornecedor
            cnpj_cpf_busca = ''.join(filter(str.isdigit, str(cnpj_cpf)))
            linha_para_excluir = None
            
            for row in range(2, ws.max_row + 1):
                cnpj_cpf_row = ws.cell(row, 1).value
                if not cnpj_cpf_row:
                    continue
                
                cnpj_cpf_row_numeros = ''.join(filter(str.isdigit, str(cnpj_cpf_row)))
                
                if cnpj_cpf_row_numeros == cnpj_cpf_busca:
                    linha_para_excluir = row
                    break
            
            if not linha_para_excluir:
                wb.close()
                custom_messagebox("error", "Erro", 
                                f"Fornecedor não encontrado na planilha!\n"
                                f"CNPJ/CPF: {cnpj_cpf}")
                return False
            
            # Excluir linha
            ws.delete_rows(linha_para_excluir, 1)
            logger.warning(f"Fornecedor EXCLUÍDO PERMANENTEMENTE: {nome} ({cnpj_cpf})")
            
            # Salvar planilha
            try:
                wb.save(ARQUIVO_FORNECEDORES)
                wb.close()
                return True
            except PermissionError:
                wb.close()
                custom_messagebox("error", "Erro de Permissão",
                                "Arquivo está aberto em outro programa!\n"
                                "Feche o Excel e tente novamente.")
                return False
                
        except Exception as e:
            logger.error(f"Erro ao excluir fornecedor: {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            custom_messagebox("error", "Erro", 
                            f"Erro ao excluir fornecedor:\n{str(e)}")
            return False
    
    def selecionar_fornecedor(self):
        """Seleciona o fornecedor e preenche seus dados"""
        try:
            logger.info("="*50)
            logger.info("INICIANDO SELEÇÃO DE FORNECEDOR")
            logger.info("="*50)
            
            selecionado = self.tree_fornecedores.selection()
            
            if not selecionado:
                custom_messagebox("warning", "Aviso", "Selecione um fornecedor na lista!")
                return
            
            valores = self.tree_fornecedores.item(selecionado[0])['values']
            tags = self.tree_fornecedores.item(selecionado[0])['tags']
            
            logger.debug(f"DEBUG SELEÇÃO:")
            logger.debug(f"  Tags RAW: {tags}")
            
            if len(valores) < 3 or valores[1] == 'Nenhum fornecedor encontrado':
                custom_messagebox("warning", "Aviso", "Selecione um fornecedor válido!")
                return
            
            # ============================================
            # REMOVER O PREFIXO "ID:" ao recuperar
            # ============================================
            cnpj_tag = tags[0] if tags and len(tags) > 0 else ''
            
            # Remover prefixo "ID:"
            if cnpj_tag.startswith('ID:'):
                cnpj_cpf_normalizado = cnpj_tag[3:]  # Remove "ID:"
            else:
                cnpj_cpf_normalizado = str(cnpj_tag)  # Fallback
            
            tipo_pessoa = tags[1] if tags and len(tags) > 1 else 'PJ'
            
            nome = str(valores[1]).strip()
            categoria = str(valores[2]).strip()
            cnpj_cpf_formatado = str(valores[0]).strip()
            
            logger.info(f"Fornecedor: {nome}")
            logger.debug(f"Tag original: {cnpj_tag}")
            logger.debug(f"CNPJ/CPF normalizado (SEM PREFIXO): {cnpj_cpf_normalizado}")
            logger.debug(f"Tipo pessoa: {tipo_pessoa}")
            logger.debug(f"CNPJ/CPF formatado: {cnpj_cpf_formatado}")
            
            # Buscar dados completos
            fornecedor_completo = self.buscar_fornecedor_completo(cnpj_cpf_normalizado)
            
            if not fornecedor_completo:
                logger.error(f"Fornecedor não encontrado: {cnpj_cpf_normalizado}")
                custom_messagebox("error", "Erro", 
                                f"Não foi possível carregar os dados do fornecedor!\n\n"
                                f"CNPJ/CPF: {cnpj_cpf_formatado}")
                return
            
            logger.info(f"Dados carregados: {fornecedor_completo['nome']}")
            
            if not hasattr(self, 'campos_fornecedor'):
                custom_messagebox("error", "Erro", "Campos de fornecedor não configurados!")
                return
            
            # === PREENCHER CAMPOS ===
            
            # CNPJ/CPF (usar formatado)
            self.campos_fornecedor['cnpj_cpf'].config(state='normal')
            self.campos_fornecedor['cnpj_cpf'].delete(0, tk.END)
            self.campos_fornecedor['cnpj_cpf'].insert(0, cnpj_cpf_formatado)
            self.campos_fornecedor['cnpj_cpf'].config(state='readonly')
            
            # Nome
            self.campos_fornecedor['nome'].config(state='normal')
            self.campos_fornecedor['nome'].delete(0, tk.END)
            self.campos_fornecedor['nome'].insert(0, nome)
            self.campos_fornecedor['nome'].config(state='readonly')
            
            # Categoria
            if isinstance(self.campos_fornecedor['categoria'], ttk.Combobox):
                self.campos_fornecedor['categoria'].set(categoria)
            else:
                self.campos_fornecedor['categoria'].config(state='normal')
                self.campos_fornecedor['categoria'].delete(0, tk.END)
                self.campos_fornecedor['categoria'].insert(0, categoria)
                self.campos_fornecedor['categoria'].config(state='readonly')
            
            # ============================================
            # PREENCHER DADOS BANCÁRIOS
            # ============================================
            dados_bancarios_planilha = fornecedor_completo.get('dados_bancarios', '').strip()
            
            self.campos_fornecedor['dados_bancarios'].config(state='normal')
            self.campos_fornecedor['dados_bancarios'].delete(0, tk.END)
            
            if dados_bancarios_planilha:
                # Se houver dados bancários na planilha, usar
                self.campos_fornecedor['dados_bancarios'].insert(0, dados_bancarios_planilha)
                logger.debug(f"Dados bancários da planilha: {dados_bancarios_planilha}")
            else:
                # Se não houver, montar dinamicamente
                logger.debug("Sem dados bancários na planilha, montando dinamicamente")
                self.atualizar_dados_bancarios()
            
            self.campos_fornecedor['dados_bancarios'].config(state='readonly')
            
            logger.info("Campos preenchidos com sucesso!")
            
            # ============================================
            # PREENCHER REFERÊNCIA COM ESPECIFICAÇÃO (Coluna M)
            # ============================================
            especificacao = fornecedor_completo.get('especificacao', '').strip()
            
            if hasattr(self, 'campos_despesa') and 'referencia' in self.campos_despesa:
                # Limpar campo de referência
                self.campos_despesa['referencia'].delete(0, tk.END)
                
                if especificacao:
                    # Inserir especificação se existir
                    self.campos_despesa['referencia'].insert(0, especificacao)
                    logger.info(f"✓ Referência preenchida: {especificacao}")
                else:
                    logger.debug("Nenhuma especificação cadastrada para este fornecedor")
            else:
                logger.warning("Campo 'referencia' não encontrado em campos_despesa")

            # ============================================
            # AVANÇAR PARA ABA DE DADOS (SEMPRE!)
            # ============================================
            if hasattr(self, 'notebook'):
                num_abas = self.notebook.index('end')
                if num_abas >= 3:
                    self.notebook.select(2)  # Seleciona aba de dados
                    logger.debug("Aba de dados selecionada")
                    
                    # Focar no primeiro campo editável
                    if hasattr(self, 'campos_despesa') and 'tp_desp' in self.campos_despesa:
                        self.campos_despesa['tp_desp'].focus()
                        logger.debug("Foco definido no campo 'tp_desp'")
            
            logger.info("SELEÇÃO CONCLUÍDA COM SUCESSO!")
            logger.info("="*50)
            
        except Exception as e:
            logger.error(f"ERRO em selecionar_fornecedor: {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            custom_messagebox("error", "Erro", f"Erro ao selecionar fornecedor:\n{str(e)}")
            
    
    def buscar_fornecedor(self):
        """
        Adiciona filtro para não exibir fornecedores INATIVOS
        """
        try:
            from src.config.utils import custom_messagebox
            from src.config.config import ARQUIVO_FORNECEDORES
            from openpyxl import load_workbook
            
            termo = self.busca_entry.get().strip()
            
            # Limpar resultados anteriores
            for item in self.tree_fornecedores.get_children():
                self.tree_fornecedores.delete(item)
            
            if not termo:
                return
            
            wb = load_workbook(ARQUIVO_FORNECEDORES, data_only=True)
            ws = wb['Fornecedores']
            
            resultados_encontrados = 0
            termo_upper = termo.upper()
            resultados = []
            
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or not row[0]:
                    continue
                
                # ============================================
                # FILTRO DE STATUS (NOVO!)
                # ============================================
                # Verificar coluna 17 (STATUS)
                status = str(row[16]).strip().upper() if len(row) > 16 and row[16] else 'ATIVO'
                
                # Pular fornecedores INATIVOS
                if status == 'INATIVO':
                    continue
                # ============================================
                
                cnpj_cpf_valor = row[0]
                tipo_pessoa = str(row[1]).strip().upper()
                nome = str(row[3] or '').strip().upper()
                categoria = str(row[11] or '').strip()
                
                # Extrair números
                cnpj_cpf_numeros = ''.join(filter(str.isdigit, str(cnpj_cpf_valor)))
                
                # Normalizar com zeros
                if tipo_pessoa == 'PF':
                    cnpj_cpf_normalizado = cnpj_cpf_numeros.zfill(11)
                else:  # PJ
                    cnpj_cpf_normalizado = cnpj_cpf_numeros.zfill(14)
                
                # Formatar para exibição
                if tipo_pessoa == 'PF':
                    cnpj_cpf_formatado = f"{cnpj_cpf_normalizado[:3]}.{cnpj_cpf_normalizado[3:6]}.{cnpj_cpf_normalizado[6:9]}-{cnpj_cpf_normalizado[9:11]}"
                else:  # PJ
                    cnpj_cpf_formatado = f"{cnpj_cpf_normalizado[:2]}.{cnpj_cpf_normalizado[2:5]}.{cnpj_cpf_normalizado[5:8]}/{cnpj_cpf_normalizado[8:12]}-{cnpj_cpf_normalizado[12:14]}"
                
                if termo_upper in nome:
                    resultados.append({
                        'values': (cnpj_cpf_formatado, nome, categoria),
                        'tags': (cnpj_cpf_normalizado, tipo_pessoa)
                    })
                    
                    resultados_encontrados += 1
                    
                    if resultados_encontrados >= 100:
                        break
            
            wb.close()
            
            # Ordenar resultados
            if resultados:
                resultados.sort(key=lambda x: x['values'][1])
            
            # Inserir resultados
            for resultado in resultados:
                cnpj_tag = f"ID:{resultado['tags'][0]}"
                tipo_tag = resultado['tags'][1]
                
                self.tree_fornecedores.insert('', 'end', 
                    values=resultado['values'],
                    tags=(cnpj_tag, tipo_tag)
                )
            
            if resultados_encontrados == 0:
                self.tree_fornecedores.insert('', 'end', values=(
                    '', 'Nenhum fornecedor encontrado', ''
                ))
                
        except Exception as e:
            logger.error(f"Erro na busca: {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            custom_messagebox("error", "Erro", f"Erro na busca: {str(e)}")


    def listar_fornecedores_inativos(self):
        """
        Abre janela para visualizar e gerenciar fornecedores INATIVOS
        VERSÃO CORRIGIDA - USA TIPO_PESSOA DA COLUNA B
        """
        try:
            from src.config.config import ARQUIVO_FORNECEDORES
            from openpyxl import load_workbook
            import logging
            
            logger = logging.getLogger(__name__)
            logger.info("="*60)
            logger.info("ABRINDO JANELA DE FORNECEDORES INATIVOS")
            logger.info("="*60)
            
            # Criar janela
            janela_inativos = tk.Toplevel(self.root)
            janela_inativos.title("Fornecedores Inativos")
            janela_inativos.geometry("900x600")
            janela_inativos.transient(self.root)
            janela_inativos.grab_set()
            
            # Centralizar
            janela_inativos.update_idletasks()
            x = (janela_inativos.winfo_screenwidth() // 2) - 450
            y = (janela_inativos.winfo_screenheight() // 2) - 300
            janela_inativos.geometry(f"900x600+{x}+{y}")
            
            main_frame = ttk.Frame(janela_inativos, padding="15")
            main_frame.pack(fill='both', expand=True)
            
            # Cabeçalho
            ttk.Label(main_frame, text="📋 Fornecedores Inativos",
                    font=('Arial', 16, 'bold')).pack(pady=(0, 15))
            
            # Frame para lista
            lista_frame = ttk.Frame(main_frame)
            lista_frame.pack(fill='both', expand=True, pady=(0, 15))
            
            # Treeview
            tree_inativos = ttk.Treeview(lista_frame,
                                        columns=('CNPJ/CPF', 'Nome', 'Categoria'),
                                        show='headings',
                                        height=20)
            
            tree_inativos.heading('CNPJ/CPF', text='CNPJ/CPF')
            tree_inativos.heading('Nome', text='Nome')
            tree_inativos.heading('Categoria', text='Categoria')
            
            tree_inativos.column('CNPJ/CPF', width=150, anchor='center')
            tree_inativos.column('Nome', width=400)
            tree_inativos.column('Categoria', width=100, anchor='center')
            
            # Scrollbar
            scroll_y = ttk.Scrollbar(lista_frame, orient='vertical', command=tree_inativos.yview)
            tree_inativos.configure(yscrollcommand=scroll_y.set)
            
            tree_inativos.pack(side='left', fill='both', expand=True)
            scroll_y.pack(side='right', fill='y')
            
            # Carregar fornecedores inativos
            logger.info("Carregando fornecedores inativos da planilha...")
            
            wb = load_workbook(ARQUIVO_FORNECEDORES, data_only=True)
            ws = wb['Fornecedores']
            
            total_inativos = 0
            
            for row_num, row in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
                if not row or not row[0]:
                    continue
                
                # Verificar STATUS (coluna 17 = índice 16)
                status = str(row[16]).strip().upper() if len(row) > 16 and row[16] else 'ATIVO'
                
                logger.debug(f"Linha {row_num}: {row[3]} - STATUS: {status}")
                
                if status == 'INATIVO':
                    # ✅ OBTER TIPO_PESSOA DA COLUNA B (índice 1)
                    tipo_pessoa = str(row[1]).strip().upper() if row[1] else 'PJ'
                    
                    # Extrair CNPJ/CPF
                    cnpj_cpf_valor = row[0]
                    cnpj_cpf_limpo = ''.join(filter(str.isdigit, str(cnpj_cpf_valor)))
                    
                    # ✅ NORMALIZAR BASEADO NO TIPO_PESSOA
                    if tipo_pessoa == 'PF':
                        cnpj_cpf_normalizado = cnpj_cpf_limpo.zfill(11)  # CPF: 11 dígitos
                        # Formatar CPF
                        cnpj_cpf_formatado = f"{cnpj_cpf_normalizado[:3]}.{cnpj_cpf_normalizado[3:6]}.{cnpj_cpf_normalizado[6:9]}-{cnpj_cpf_normalizado[9:11]}"
                    else:  # PJ
                        cnpj_cpf_normalizado = cnpj_cpf_limpo.zfill(14)  # CNPJ: 14 dígitos
                        # Formatar CNPJ
                        cnpj_cpf_formatado = f"{cnpj_cpf_normalizado[:2]}.{cnpj_cpf_normalizado[2:5]}.{cnpj_cpf_normalizado[5:8]}/{cnpj_cpf_normalizado[8:12]}-{cnpj_cpf_normalizado[12:14]}"
                    
                    nome = str(row[3] or '').strip()
                    categoria = str(row[11] or '').strip()
                    
                    # ✅ ARMAZENAR CNPJ/CPF NORMALIZADO E TIPO_PESSOA NAS TAGS
                    tree_inativos.insert('', 'end',
                                    values=(cnpj_cpf_formatado, nome, categoria),
                                    tags=(cnpj_cpf_normalizado, tipo_pessoa))  # ← CNPJ + TIPO
                    
                    total_inativos += 1
                    
                    logger.debug(f"  ✓ Adicionado: {nome}")
                    logger.debug(f"    Tipo: {tipo_pessoa}")
                    logger.debug(f"    CNPJ/CPF normalizado: {cnpj_cpf_normalizado}")
            
            wb.close()
            
            logger.info(f"Total de fornecedores inativos encontrados: {total_inativos}")
            
            # Botões
            botoes_frame = ttk.Frame(main_frame)
            botoes_frame.pack(fill='x')
            
            ttk.Label(botoes_frame, text=f"Total: {total_inativos} fornecedor(es) inativo(s)",
                    font=('Arial', 10, 'bold')).pack(side='left', padx=10)
            
            def reativar_selecionado():
                """Reativa o fornecedor selecionado"""
                try:
                    from src.config.utils import custom_messagebox
                    
                    logger.info("="*60)
                    logger.info("INICIANDO REATIVAÇÃO DE FORNECEDOR")
                    logger.info("="*60)
                    
                    selecionado = tree_inativos.selection()
                    
                    if not selecionado:
                        logger.warning("Nenhum fornecedor selecionado")
                        custom_messagebox("warning", "Aviso", "⚠️ Selecione um fornecedor!")
                        return
                    
                    # Obter dados do item selecionado
                    valores = tree_inativos.item(selecionado[0])['values']
                    tags = tree_inativos.item(selecionado[0])['tags']
                    
                    logger.debug(f"Valores: {valores}")
                    logger.debug(f"Tags: {tags}")
                    
                    if not valores or len(valores) < 2:
                        logger.error("Dados inválidos do fornecedor selecionado")
                        custom_messagebox("error", "Erro", "❌ Dados inválidos!")
                        return
                    
                    cnpj_cpf_formatado = valores[0]
                    nome = valores[1]
                    
                    # ✅ OBTER CNPJ/CPF E TIPO_PESSOA DAS TAGS
                    if tags and len(tags) >= 2:
                        cnpj_cpf = tags[0]  # CNPJ normalizado
                        tipo_pessoa = tags[1]  # PF ou PJ
                    else:
                        logger.error("Tags inválidas")
                        custom_messagebox("error", "Erro", "❌ Dados inválidos!")
                        return
                    
                    logger.info(f"Reativando fornecedor:")
                    logger.info(f"  Nome: {nome}")
                    logger.info(f"  Tipo: {tipo_pessoa}")
                    logger.info(f"  CNPJ/CPF formatado: {cnpj_cpf_formatado}")
                    logger.info(f"  CNPJ/CPF normalizado: {cnpj_cpf}")
                    
                    # ✅ CHAMAR MÉTODO COM TIPO_PESSOA
                    sucesso = self.reativar_fornecedor(cnpj_cpf, tipo_pessoa, nome)
                    
                    if sucesso:
                        logger.info("✅ Fornecedor reativado com sucesso!")
                        
                        # Remover da lista
                        tree_inativos.delete(selecionado[0])
                        
                        # Atualizar contador
                        total_restante = len(tree_inativos.get_children())
                        botoes_frame.winfo_children()[0].config(
                            text=f"Total: {total_restante} fornecedor(es) inativo(s)"
                        )
                        
                        custom_messagebox("info", "Sucesso",
                                        f"✅ Fornecedor reativado com sucesso!\n\n"
                                        f"Nome: {nome}\n"
                                        f"CNPJ/CPF: {cnpj_cpf_formatado}\n\n"
                                        f"O fornecedor voltará a aparecer nas buscas.")
                    else:
                        logger.error("❌ Falha ao reativar fornecedor")
                        custom_messagebox("error", "Erro",
                                        f"❌ Não foi possível reativar o fornecedor.\n\n"
                                        f"Verifique os logs para mais detalhes.")
                    
                    logger.info("="*60)
                    
                except Exception as e:
                    logger.error(f"ERRO em reativar_selecionado: {str(e)}")
                    import traceback
                    logger.error(traceback.format_exc())
                    custom_messagebox("error", "Erro", 
                                    f"❌ Erro ao reativar fornecedor:\n{str(e)}")
            
            ttk.Button(botoes_frame, text="✅ Reativar Selecionado",
                    command=reativar_selecionado).pack(side='right', padx=5)
            
            ttk.Button(botoes_frame, text="Fechar",
                    command=janela_inativos.destroy).pack(side='right', padx=5)
            
            logger.info("Janela de fornecedores inativos aberta com sucesso")
            
        except Exception as e:
            logger.error(f"ERRO ao abrir janela de inativos: {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            from src.config.utils import custom_messagebox
            custom_messagebox("error", "Erro", f"Erro ao listar inativos:\n{str(e)}")


    def reativar_fornecedor(self, cnpj_cpf, tipo_pessoa, nome):
        """
        Reativa um fornecedor que estava INATIVO
        VERSÃO CORRIGIDA - USA TIPO_PESSOA PARA NORMALIZAR
        
        Args:
            cnpj_cpf: CNPJ/CPF do fornecedor (normalizado com zeros)
            tipo_pessoa: 'PF' ou 'PJ' (da coluna B)
            nome: Nome do fornecedor (para log)
        
        Returns:
            bool: True se reativado com sucesso, False caso contrário
        """
        try:
            from src.config.config import ARQUIVO_FORNECEDORES
            from openpyxl import load_workbook
            import logging
            
            logger = logging.getLogger(__name__)
            
            logger.info("="*60)
            logger.info("MÉTODO: reativar_fornecedor()")
            logger.info("="*60)
            logger.info(f"CNPJ/CPF recebido: '{cnpj_cpf}' (type: {type(cnpj_cpf).__name__})")
            logger.info(f"Tipo Pessoa: '{tipo_pessoa}'")
            logger.info(f"Nome: '{nome}'")
            
            # ✅ GARANTIR QUE CNPJ/CPF ESTÁ NORMALIZADO
            cnpj_cpf_limpo = ''.join(filter(str.isdigit, str(cnpj_cpf)))
            
            if tipo_pessoa == 'PF':
                cnpj_cpf_normalizado = cnpj_cpf_limpo.zfill(11)  # CPF: 11 dígitos
            else:  # PJ
                cnpj_cpf_normalizado = cnpj_cpf_limpo.zfill(14)  # CNPJ: 14 dígitos
            
            logger.info(f"CNPJ/CPF normalizado: '{cnpj_cpf_normalizado}' (len={len(cnpj_cpf_normalizado)})")
            
            # Abrir planilha
            logger.debug(f"Abrindo planilha: {ARQUIVO_FORNECEDORES}")
            wb = load_workbook(ARQUIVO_FORNECEDORES)
            ws = wb['Fornecedores']
            
            logger.debug(f"Planilha aberta. Total de linhas: {ws.max_row}")
            
            # Buscar fornecedor e marcar como ATIVO
            fornecedor_encontrado = False
            linha_encontrada = None
            
            for row_num in range(2, ws.max_row + 1):
                cnpj_cpf_row = ws.cell(row_num, 1).value  # Coluna A
                tipo_pessoa_row = ws.cell(row_num, 2).value  # Coluna B
                
                if not cnpj_cpf_row:
                    continue
                
                # ✅ OBTER TIPO_PESSOA DA PLANILHA
                tipo_pessoa_row_upper = str(tipo_pessoa_row).strip().upper() if tipo_pessoa_row else 'PJ'
                
                # ✅ NORMALIZAR CNPJ/CPF DA PLANILHA BASEADO NO TIPO
                cnpj_cpf_row_limpo = ''.join(filter(str.isdigit, str(cnpj_cpf_row)))
                
                if tipo_pessoa_row_upper == 'PF':
                    cnpj_cpf_row_normalizado = cnpj_cpf_row_limpo.zfill(11)
                else:
                    cnpj_cpf_row_normalizado = cnpj_cpf_row_limpo.zfill(14)
                
                # Log para debug (primeiras linhas ou quando encontrar)
                if row_num <= 3 or cnpj_cpf_row_normalizado == cnpj_cpf_normalizado:
                    logger.debug(f"Linha {row_num}:")
                    logger.debug(f"  CNPJ planilha original: '{cnpj_cpf_row}'")
                    logger.debug(f"  Tipo planilha: '{tipo_pessoa_row_upper}'")
                    logger.debug(f"  CNPJ planilha normalizado: '{cnpj_cpf_row_normalizado}'")
                    logger.debug(f"  CNPJ busca normalizado: '{cnpj_cpf_normalizado}'")
                    logger.debug(f"  Match? {cnpj_cpf_row_normalizado == cnpj_cpf_normalizado}")
                
                # ✅ COMPARAR VALORES NORMALIZADOS
                if cnpj_cpf_row_normalizado == cnpj_cpf_normalizado:
                    # ✅ FORNECEDOR ENCONTRADO!
                    logger.info(f"✅ FORNECEDOR ENCONTRADO NA LINHA {row_num}!")
                    
                    status_anterior = ws.cell(row_num, 17).value
                    logger.info(f"  STATUS anterior: '{status_anterior}'")
                    
                    # Marcar como ATIVO
                    ws.cell(row_num, 17, 'ATIVO')
                    logger.info(f"  STATUS novo: 'ATIVO'")
                    
                    fornecedor_encontrado = True
                    linha_encontrada = row_num
                    break
            
            if not fornecedor_encontrado:
                logger.warning(f"❌ Fornecedor NÃO ENCONTRADO!")
                logger.warning(f"  Buscou por CNPJ/CPF: '{cnpj_cpf_normalizado}' (tipo: {tipo_pessoa})")
                logger.warning(f"  Total de linhas verificadas: {ws.max_row - 1}")
                wb.close()
                return False
            
            # Salvar planilha
            logger.info("Salvando planilha...")
            
            try:
                wb.save(ARQUIVO_FORNECEDORES)
                logger.info("✅ Planilha salva com sucesso!")
                
            except PermissionError:
                logger.error("❌ ERRO: Arquivo está aberto em outro programa!")
                wb.close()
                from src.config.utils import custom_messagebox
                custom_messagebox("error", "Erro de Permissão",
                                "❌ Arquivo está aberto no Excel!\n\n"
                                "Feche o arquivo e tente novamente.")
                return False
            
            wb.close()
            
            logger.info(f"✅ Fornecedor '{nome}' reativado com sucesso!")
            logger.info(f"   Linha: {linha_encontrada}")
            logger.info(f"   Tipo: {tipo_pessoa}")
            logger.info(f"   STATUS: INATIVO → ATIVO")
            logger.info("="*60)
            
            return True
            
        except Exception as e:
            logger.error(f"❌ ERRO CRÍTICO em reativar_fornecedor: {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            
            try:
                wb.close()
            except:
                pass
            
            return False
    
    def buscar_fornecedores_por_nome_parcial(self, nome_parcial):
        """
        Busca otimizada por nome parcial usando cache
        VERSÃO FINAL OTIMIZADA
        """
        try:
            if not nome_parcial or len(nome_parcial) < 3:
                return []
            
            # Carregar fornecedores do cache
            fornecedores = self.cache_fornecedores.carregar_cache_se_necessario(ARQUIVO_FORNECEDORES)
            
            if not fornecedores:
                logger.debug("DEBUG: Cache vazio, fazendo busca direta")
                return self.buscar_fornecedores_por_nome_parcial_direto(nome_parcial)
            
            nome_busca = nome_parcial.strip().upper()
            fornecedores_encontrados = []
            
            logger.debug(f"DEBUG: Buscando '{nome_busca}' em {len(fornecedores)} fornecedores do cache")
            
            for fornecedor in fornecedores:
                nome = fornecedor['nome']
                
                if nome_busca in nome:
                    # Calcular relevância (posição no nome)
                    posicao = nome.find(nome_busca)
                    relevancia = 1000 - posicao
                    
                    fornecedor_resultado = fornecedor.copy()
                    fornecedor_resultado['relevancia'] = relevancia
                    
                    fornecedores_encontrados.append(fornecedor_resultado)
                    
                    # Limitar resultados para performance
                    if len(fornecedores_encontrados) >= 15:
                        break
            
            # Ordenar por relevância
            fornecedores_encontrados.sort(key=lambda x: (-x['relevancia'], x['nome']))
            
            logger.debug(f"DEBUG: {len(fornecedores_encontrados)} fornecedores encontrados no cache")
            
            return fornecedores_encontrados
            
        except Exception as e:
            logger.debug(f"DEBUG: Erro na busca por cache: {str(e)}")
            # Fallback para busca direta
            return self.buscar_fornecedores_por_nome_parcial_direto(nome_parcial)

    def buscar_fornecedor_completo(self, cnpj_cpf):
        """
        Busca fornecedor completo - VERSÃO ROBUSTA
        Busca tanto por valor texto quanto por números
        """
        try:
            from src.config.config import ARQUIVO_FORNECEDORES
            from openpyxl import load_workbook
            import os
            
            logger.debug(f"=== buscar_fornecedor_completo ===")
            logger.debug(f"CNPJ/CPF recebido: {cnpj_cpf}")
            
            if not os.path.exists(ARQUIVO_FORNECEDORES):
                logger.error(f"Arquivo não encontrado")
                return None
            
            wb = load_workbook(ARQUIVO_FORNECEDORES, data_only=True)
            ws = wb['Fornecedores']
            
            # Preparar valores de busca
            cnpj_cpf_busca_str = str(cnpj_cpf).strip()
            cnpj_cpf_busca_numeros = ''.join(filter(str.isdigit, cnpj_cpf_busca_str))
            
            logger.debug(f"Buscando por:")
            logger.debug(f"  String: '{cnpj_cpf_busca_str}'")
            logger.debug(f"  Números: '{cnpj_cpf_busca_numeros}' (len={len(cnpj_cpf_busca_numeros)})")
            
            total_linhas = 0
            fornecedor_encontrado = None
            
            for linha, row in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
                if not row or not row[0]:
                    continue
                
                total_linhas += 1
                
                row_cnpj_valor = row[0]
                row_tipo_pessoa = str(row[1]).strip().upper()
                
                # ============================================
                # ESTRATÉGIA 1: Comparar como STRING (exato)
                # ============================================
                row_cnpj_str = str(row_cnpj_valor).strip()
                
                # ============================================
                # ESTRATÉGIA 2: Comparar NÚMEROS (sem formatação)
                # ============================================
                row_cnpj_numeros = ''.join(filter(str.isdigit, str(row_cnpj_valor)))
                
                # Log para debug (apenas primeiras linhas ou match)
                if total_linhas <= 3 or row_cnpj_numeros == cnpj_cpf_busca_numeros:
                    logger.debug(f"Linha {linha}:")
                    logger.debug(f"  Valor planilha: '{row_cnpj_valor}' (type={type(row_cnpj_valor).__name__})")
                    logger.debug(f"  String: '{row_cnpj_str}'")
                    logger.debug(f"  Números: '{row_cnpj_numeros}'")
                
                # ============================================
                # COMPARAÇÃO MÚLTIPLA (funciona em todos os casos)
                # ============================================
                match = False
                
                # Teste 1: Comparação de números
                if row_cnpj_numeros == cnpj_cpf_busca_numeros:
                    match = True
                    logger.debug(f"  ✓ MATCH por NÚMEROS!")
                
                # Teste 2: Comparação de string (caso a planilha tenha exatamente o valor)
                elif row_cnpj_str == cnpj_cpf_busca_str:
                    match = True
                    logger.debug(f"  ✓ MATCH por STRING!")
                
                if match:
                    logger.info(f"✓ FORNECEDOR ENCONTRADO NA LINHA {linha}!")
                    logger.debug(f"  Tipo: {row_tipo_pessoa}")
                    logger.debug(f"  CNPJ/CPF planilha: {row_cnpj_valor}")
                    
                    row_completa = list(row) + [None] * (18 - len(row))
                    
                    fornecedor_encontrado = {
                        'cnpj_cpf': str(row_completa[0]).strip() if row_completa[0] else '',
                        'tipo_pessoa': str(row_completa[1]).strip() if row_completa[1] else '',
                        'razao_social': str(row_completa[2]).strip() if row_completa[2] else '',
                        'nome': str(row_completa[3]).strip() if row_completa[3] else '',
                        'telefone': str(row_completa[4]).strip() if row_completa[4] else '',
                        'email': str(row_completa[5]).strip() if row_completa[5] else '',
                        'banco': str(row_completa[6]).strip() if row_completa[6] else '',
                        'op': str(row_completa[7]).strip() if row_completa[7] else '',
                        'agencia': str(row_completa[8]).strip() if row_completa[8] else '',
                        'conta': str(row_completa[9]).strip() if row_completa[9] else '',
                        'chave_pix': str(row_completa[10]).strip() if row_completa[10] else '',
                        'categoria': str(row_completa[11]).strip() if row_completa[11] else '',
                        'especificacao': str(row_completa[12]).strip() if row_completa[12] else '',
                        'vinculo': str(row_completa[13]).strip() if row_completa[13] else '',
                        'dados_bancarios': str(row_completa[14]).strip() if row_completa[14] else '',
                        'endereco': str(row_completa[15]).strip() if row_completa[15] else '',
                        'status': str(row_completa[16]).strip() if row_completa[16] else '',
                        'responsavel': str(row_completa[17]).strip() if row_completa[17] else ''
                    }
                    
                    break
            
            wb.close()
            
            if not fornecedor_encontrado:
                logger.warning(f"✗ NÃO ENCONTRADO após {total_linhas} linhas")
                logger.warning(f"  Buscou por números: {cnpj_cpf_busca_numeros}")
                logger.warning(f"  Buscou por string: {cnpj_cpf_busca_str}")
            
            return fornecedor_encontrado
            
        except Exception as e:
            logger.error(f"Erro: {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            
            try:
                wb.close()
            except:
                pass
            
            return None

    def buscar_fornecedor_por_cnpj(self, cnpj_cpf):
        """Busca e seleciona fornecedor pelo CNPJ/CPF"""
        try:
            fornecedor = self.buscar_fornecedor_completo(cnpj_cpf)
            if fornecedor:
                # Preencher dados do fornecedor encontrado
                self.campos_fornecedor['nome'].delete(0, tk.END)
                self.campos_fornecedor['nome'].insert(0, fornecedor['nome'])
                
                if fornecedor.get('categoria'):
                    self.campos_fornecedor['categoria'].delete(0, tk.END)
                    self.campos_fornecedor['categoria'].insert(0, fornecedor['categoria'])
                
                # Preencher dados bancários baseado na forma de pagamento padrão
                if fornecedor.get('chave_pix'):
                    dados_bancarios = f"PIX: {fornecedor['chave_pix']}"
                else:
                    # Construir dados para TED
                    partes_dados = []
                    if fornecedor.get('banco'): partes_dados.append(fornecedor['banco'])
                    if fornecedor.get('op'): partes_dados.append(fornecedor['op'])
                    if fornecedor.get('agencia'): partes_dados.append(fornecedor['agencia'])
                    if fornecedor.get('conta'): partes_dados.append(fornecedor['conta'])
                    partes_dados.append(fornecedor['cnpj_cpf'])
                    dados_bancarios = ' - '.join(partes_dados)
                
                self.campos_despesa['dados_bancarios'].delete(0, tk.END)
                self.campos_despesa['dados_bancarios'].insert(0, dados_bancarios)
                
                logger.debug(f"DEBUG: Fornecedor encontrado e dados preenchidos: {fornecedor['nome']}")
                return True
            else:
                logger.debug(f"DEBUG: Fornecedor não encontrado para CNPJ/CPF: {cnpj_cpf}")
                return False
                
        except Exception as e:
            logger.debug(f"DEBUG: Erro ao buscar fornecedor por CNPJ: {str(e)}")
            return False

    def buscar_fornecedor_por_nome_agenda(self, nome_fornecedor):
        """Busca fornecedor pelo nome para uso na agenda"""
        try:
            if not nome_fornecedor or not nome_fornecedor.strip():
                return None
            
            # Abrir planilha de fornecedores
            wb = load_workbook(ARQUIVO_FORNECEDORES, data_only=True)
            ws = wb['Fornecedores']
            
            nome_busca = nome_fornecedor.strip().upper()
            fornecedor_encontrado = None
            melhor_match = 0
            
            # Buscar na planilha
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row[0]:  # Pular linhas vazias
                    continue
                    
                cnpj_cpf = str(row[0]).strip()           # Coluna A
                nome = str(row[3] or '').strip().upper() # Coluna D = Nome
                
                # Verificar correspondência
                if nome_busca in nome:
                    # Calcular qualidade do match
                    match_quality = len(nome_busca) / len(nome) if nome else 0
                    
                    # Se for match exato ou melhor que o anterior
                    if nome_busca == nome or match_quality > melhor_match:
                        melhor_match = match_quality
                        fornecedor_encontrado = {
                            'cnpj_cpf': cnpj_cpf,
                            'nome': nome,
                            'categoria': str(row[11] or '').strip(),      # Coluna L = CATEGORIA
                            'telefone': str(row[4] or '').strip(),        # Coluna E = TELEFONE
                            'email': str(row[5] or '').strip(),           # Coluna F = EMAIL
                            'banco': str(row[6] or '').strip(),           # Coluna G = BANCO
                            'op': str(row[7] or '').strip(),              # Coluna H = OP
                            'agencia': str(row[8] or '').strip(),         # Coluna I = AGENC
                            'conta': str(row[9] or '').strip(),           # Coluna J = CONTA
                            'chave_pix': str(row[10] or '').strip(),      # Coluna K = Chave_PIX ← CORRIGIDO!
                            'dados_bancarios': str(row[14] or '').strip() # Coluna O = DADOS BANCÁRIOS
                        }
                        
                        # Se for match exato, parar a busca
                        if nome_busca == nome:
                            break
            
            wb.close()
            
            if fornecedor_encontrado:
                logger.debug(f"DEBUG: Fornecedor encontrado: {fornecedor_encontrado['nome']} - {fornecedor_encontrado['cnpj_cpf']}")
                logger.debug(f"DEBUG: Chave PIX: {fornecedor_encontrado['chave_pix']}")
                logger.debug(f"DEBUG: Dados bancários: {fornecedor_encontrado['dados_bancarios']}")
            else:
                logger.debug(f"DEBUG: Nenhum fornecedor encontrado para: {nome_fornecedor}")
            
            return fornecedor_encontrado
            
        except Exception as e:
            logger.debug(f"DEBUG: Erro ao buscar fornecedor por nome: {str(e)}")
            import traceback
            logger.debug(traceback.format_exc())
            return None
    
    def buscar_fornecedor_por_cnpj_agenda(self, cnpj_cpf):
        """Busca fornecedor pelo CNPJ/CPF para uso na agenda"""
        try:
            if not cnpj_cpf or not cnpj_cpf.strip():
                return None
            
            # Limpar formatação do CNPJ/CPF
            cnpj_limpo = ''.join(filter(str.isdigit, cnpj_cpf))
            
            # Abrir planilha de fornecedores
            wb = load_workbook(ARQUIVO_FORNECEDORES, data_only=True)
            ws = wb['Fornecedores']
            
            # Buscar na planilha
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row[0]:  # Pular linhas vazias
                    continue
                    
                cnpj_planilha = ''.join(filter(str.isdigit, str(row[0])))
                
                if cnpj_limpo == cnpj_planilha:
                    fornecedor = {
                        'cnpj_cpf': str(row[0]).strip(),              # Coluna A
                        'nome': str(row[3] or '').strip().upper(),    # Coluna D = NOME
                        'categoria': str(row[11] or '').strip(),      # Coluna L = CATEGORIA
                        'telefone': str(row[4] or '').strip(),        # Coluna E = TELEFONE
                        'email': str(row[5] or '').strip(),           # Coluna F = EMAIL
                        'banco': str(row[6] or '').strip(),           # Coluna G = BANCO
                        'op': str(row[7] or '').strip(),              # Coluna H = OP
                        'agencia': str(row[8] or '').strip(),         # Coluna I = AGENC
                        'conta': str(row[9] or '').strip(),           # Coluna J = CONTA
                        'chave_pix': str(row[10] or '').strip(),      # Coluna K = Chave_PIX ← CORRIGIDO!
                        'dados_bancarios': str(row[14] or '').strip() # Coluna O = DADOS BANCÁRIOS
                    }
                    
                    wb.close()
                    logger.debug(f"DEBUG: Fornecedor encontrado por CNPJ: {fornecedor['nome']}")
                    logger.debug(f"DEBUG: Chave PIX: {fornecedor['chave_pix']}")
                    logger.debug(f"DEBUG: Dados bancários: {fornecedor['dados_bancarios']}")
                    return fornecedor
            
            wb.close()
            logger.debug(f"DEBUG: Nenhum fornecedor encontrado para CNPJ: {cnpj_cpf}")
            return None
            
        except Exception as e:
            logger.debug(f"DEBUG: Erro ao buscar fornecedor por CNPJ: {str(e)}")
            import traceback
            logger.debug(traceback.format_exc())
            return None

    def buscar_fornecedor_por_cnpj_agenda_manual(self, cnpj_cpf):
        """Método auxiliar para buscar e preencher dados do fornecedor"""
        try:
            # Usar o método que você já tem para buscar fornecedor
            fornecedor = self.buscar_fornecedor_por_cnpj_agenda(cnpj_cpf)
            
            if fornecedor:
                # Preencher campos do fornecedor se encontrado
                if fornecedor.get('nome'):
                    self.campos_fornecedor['nome'].delete(0, tk.END)
                    self.campos_fornecedor['nome'].insert(0, fornecedor['nome'])
                
                if fornecedor.get('categoria'):
                    # Verificar se campo categoria existe
                    if hasattr(self, 'campos_fornecedor') and 'categoria' in self.campos_fornecedor:
                        self.campos_fornecedor['categoria'].delete(0, tk.END)
                        self.campos_fornecedor['categoria'].insert(0, fornecedor['categoria'])
                
                # Preencher dados bancários se existir o campo
                dados_bancarios = self.obter_dados_bancarios_fornecedor(cnpj_cpf)
                if hasattr(self, 'campos_fornecedor') and 'dados_bancarios' in self.campos_fornecedor:
                    campo_dados_bancarios = self.campos_fornecedor['dados_bancarios']
                    campo_dados_bancarios.config(state='normal')  # Habilitar temporariamente
                    campo_dados_bancarios.delete(0, tk.END)
                    campo_dados_bancarios.insert(0, dados_bancarios)
                    campo_dados_bancarios.config(state='readonly')  # Voltar ao readonly
                
                logger.debug(f"DEBUG: Dados do fornecedor preenchidos: {fornecedor['nome']}")
                return True
            else:
                logger.debug(f"DEBUG: Fornecedor não encontrado para CNPJ/CPF: {cnpj_cpf}")
                return False
                
        except Exception as e:
            logger.debug(f"DEBUG: Erro ao buscar fornecedor para agenda: {str(e)}")
            return False
    
    
    def buscar_dados_bancarios(self, cnpj_cpf):
        try:
            wb = load_workbook(ARQUIVO_FORNECEDORES, data_only=True)
            ws = wb['Fornecedores']
        
            for row in ws.iter_rows(min_row=2, values_only=True):
                if row[0] == cnpj_cpf:
                    logger.debug(f"CNPJ/CPF encontrado: {cnpj_cpf}")
                    logger.debug(f"Dados da linha: {row}")
                    if row[14]:  # coluna O com dados bancários consolidados
                        return row[14]
                    return ""
            return ""
        except Exception as e:
            logger.debug(f"Erro ao buscar dados bancários: {e}")
            return ""

    def obter_dados_bancarios_fornecedor(self, cnpj_cpf, forma_pagamento_preferida="PIX"):
        """Obtém dados bancários formatados do fornecedor"""
        logger.debug(f"DEBUG ===== obter_dados_bancarios_fornecedor =====")
        logger.debug(f"DEBUG: cnpj_cpf recebido: '{cnpj_cpf}'")
        logger.debug(f"DEBUG: forma_pagamento: '{forma_pagamento_preferida}'")
        
        try:
            fornecedor = self.buscar_fornecedor_por_cnpj_agenda(cnpj_cpf)
            
            logger.debug(f"DEBUG: Fornecedor retornado: {fornecedor}")
            
            if not fornecedor:
                logger.debug(f"DEBUG: Fornecedor não encontrado - retornando vazio")
                return ""
            
            # PRIORIDADE 1: Usar coluna DADOS BANCÁRIOS se já estiver preenchida
            dados_bancarios_coluna = fornecedor.get('dados_bancarios', '').strip()
            if dados_bancarios_coluna:
                logger.debug(f"DEBUG: Usando dados da coluna DADOS BANCÁRIOS: '{dados_bancarios_coluna}'")
                return dados_bancarios_coluna
            
            # PRIORIDADE 2: Construir dados baseado na forma de pagamento PIX
            if forma_pagamento_preferida == "PIX":
                chave_pix = fornecedor.get('chave_pix', '').strip()
                if chave_pix:
                    resultado = f"PIX: {chave_pix}"
                    logger.debug(f"DEBUG: Construindo dados PIX: '{resultado}'")
                    return resultado
                else:
                    logger.debug(f"DEBUG: Chave PIX não cadastrada - retornando vazio")
                    return ""
            
            # PRIORIDADE 3: Construir dados para TED (apenas se houver dados completos)
            partes_dados = []
            
            if fornecedor.get('banco'): 
                partes_dados.append(fornecedor['banco'])
            if fornecedor.get('op'): 
                partes_dados.append(fornecedor['op'])
            if fornecedor.get('agencia'): 
                partes_dados.append(fornecedor['agencia'])
            if fornecedor.get('conta'): 
                partes_dados.append(fornecedor['conta'])
            
            # Só adicionar CNPJ/CPF se houver pelo menos um dado bancário
            if partes_dados:
                partes_dados.append(fornecedor['cnpj_cpf'])
                resultado = ' - '.join(partes_dados)
                logger.debug(f"DEBUG: Construindo dados TED: '{resultado}'")
                return resultado
            else:
                # Se não houver nenhum dado bancário, retornar vazio
                logger.debug(f"DEBUG: Nenhum dado bancário cadastrado - retornando vazio")
                return ""
            
        except Exception as e:
            logger.debug(f"DEBUG: ERRO em obter_dados_bancarios_fornecedor: {str(e)}")
            import traceback
            logger.debug(traceback.format_exc())
            return ""
    
    def atualizar_resumo_dados_bancarios(self, event=None):
        """Atualiza o campo de resumo dos dados bancários em tempo real"""
        try:
            # Obter chave PIX
            chave_pix = self.campos_form['chave_pix'].get().strip()
            
            if chave_pix:
                # FORMA 1: Pagamento via PIX
                dados_consolidados = f"PIX: {chave_pix}"
            else:
                # Verificar se tem dados bancários para TED
                banco = self.campos_form['banco'].get().strip()
                op = self.campos_form['op'].get().strip()
                agencia = self.campos_form['agencia'].get().strip()
                conta = self.campos_form['conta'].get().strip()
                cnpj_cpf = self.campos_form['cnpj_cpf'].get().strip()
                
                # FORMA 2: Pagamento via TED (precisa de todos os dados)
                if banco and agencia and conta and cnpj_cpf:
                    partes = [banco]
                    if op:
                        partes.append(f"Op: {op}")
                    partes.append(f"Ag: {agencia}")
                    partes.append(f"Conta: {conta}")
                    partes.append(f"CNPJ/CPF: {cnpj_cpf}")
                    
                    dados_consolidados = " | ".join(partes)
                # FORMA 3: Pagamento em DINHEIRO (não precisa de dados bancários)
                else:
                    dados_consolidados = "NENHUM DADO BANCÁRIO CADASTRADO"
            
            # Atualizar campo display
            self.campos_form['dados_bancarios_display'].config(state='normal')
            self.campos_form['dados_bancarios_display'].delete(0, tk.END)
            self.campos_form['dados_bancarios_display'].insert(0, dados_consolidados)
            self.campos_form['dados_bancarios_display'].config(state='readonly')
            
        except Exception as e:
            logger.debug(f"Erro ao atualizar resumo bancário: {str(e)}")

    def limpar_todos_dados_bancarios(self):
        """Limpa todos os campos de dados bancários de uma vez, evitando inconsistências"""
        resposta = messagebox.askyesno(
            "Confirmação",
            "⚠️ Deseja realmente limpar TODOS os dados bancários?\n\n"
            "Isso incluirá:\n"
            "• Banco\n"
            "• Operação\n"
            "• Agência\n"
            "• Conta\n"
            "• Chave PIX\n\n"
            "Esta ação não pode ser desfeita!",
            icon='warning'
        )
        
        if resposta:
            # Limpar todos os campos bancários
            self.campos_form['banco'].set('')
            self.campos_form['op'].delete(0, tk.END)
            self.campos_form['agencia'].delete(0, tk.END)
            self.campos_form['conta'].delete(0, tk.END)
            self.campos_form['chave_pix'].delete(0, tk.END)
            self.tipo_pix.set('Selecione')
            
            # Atualizar resumo
            self.atualizar_resumo_dados_bancarios()
            
            custom_messagebox("info", "Dados Limpos", 
                            "✅ Todos os dados bancários foram removidos!")

    def validar_cnpj_cpf_numeros(self, numeros):
        """Valida CNPJ/CPF usando apenas os números"""
        if len(numeros) == 11:
            # Validar CPF
            return validar_documento(f"{numeros[:3]}.{numeros[3:6]}.{numeros[6:9]}-{numeros[9:]}")
        elif len(numeros) == 14:
            # Validar CNPJ
            return validar_documento(f"{numeros[:2]}.{numeros[2:5]}.{numeros[5:8]}/{numeros[8:12]}-{numeros[12:]}")
        return False

    def usar_cpf_criado_auto(self):
        """Busca e usa automaticamente o próximo CPF criado disponível - VERSÃO MELHORADA"""
        try:
            if not hasattr(self, 'gerenciador_cpfs'):
                self.gerenciador_cpfs = GerenciadorCPFsCriados()
            
            logger.debug("Iniciando busca por CPF disponível...")
            cpf_disponivel, linha = self.gerenciador_cpfs.obter_proximo_cpf_disponivel()
            
            if cpf_disponivel:
                logger.debug(f"CPF obtido: {cpf_disponivel}")
                
                # TESTE: Validar o CPF antes de usar
                if not self.gerenciador_cpfs.validar_cpf_gerado(cpf_disponivel):
                    custom_messagebox("error", "Erro", 
                                    f"❌ CPF gerado é inválido: {cpf_disponivel}\n\n"
                                    f"Verifique o algoritmo de geração")
                    return
                
                # Formatar CPF
                cpf_formatado = f"{cpf_disponivel[:3]}.{cpf_disponivel[3:6]}.{cpf_disponivel[6:9]}-{cpf_disponivel[9:]}"
                logger.debug(f"CPF formatado: {cpf_formatado}")
                
                # TESTE: Validar CPF formatado com a função do sistema
                try:
                    if not validar_documento(cpf_formatado):
                        logger.debug(f"AVISO: Sistema não reconheceu CPF como válido: {cpf_formatado}")
                        # Mesmo assim, continuar - pode ser problema na função validar_documento
                except Exception as e:
                    logger.debug(f"Erro na validação do sistema: {str(e)}")
                
                # Preencher campo CNPJ/CPF
                self.campos_form['cnpj_cpf'].delete(0, tk.END)
                self.campos_form['cnpj_cpf'].insert(0, cpf_formatado)
                
                # Definir como PF
                self.campos_form['tipo_pessoa'].set('PF')
                
                # Configurar PIX automaticamente
                self.tipo_pix.set('CNPJ/CPF')
                self.campos_form['chave_pix'].delete(0, tk.END)
                self.campos_form['chave_pix'].insert(0, cpf_formatado)
                
                # Focar no campo nome para continuar o cadastro
                self.campos_form['razao_social'].focus()
                
                custom_messagebox("info", "CPF Obtido", 
                                f"✅ CPF criado obtido com sucesso!\n\n"
                                f"📋 CPF: {cpf_formatado}\n"
                                f"🔑 Configurado como chave PIX\n"
                                f"🔍 Validação: CPF matematicamente correto\n\n"
                                f"➡️ Continue preenchendo os dados do prestador")
            else:
                custom_messagebox("error", "Erro", 
                                "❌ Não foi possível obter um CPF criado.\n\n"
                                "Possíveis causas:\n"
                                "• Arquivo Base_Fornecedores.xlsx não encontrado\n"
                                "• Erro na geração de CPFs válidos\n"
                                "• Problema de permissão no arquivo")
                
        except Exception as e:
            logger.debug(f"Erro detalhado: {str(e)}")
            import traceback
            logger.debug(traceback.format_exc())
            custom_messagebox("error", "Erro", f"❌ Erro ao obter CPF criado:\n{str(e)}")

    def mostrar_cpfs_disponiveis(self):
        """Mostra lista de CPFs disponíveis para seleção manual"""
        try:
            if not hasattr(self, 'gerenciador_cpfs'):
                self.gerenciador_cpfs = GerenciadorCPFsCriados()
                
            cpfs_disponiveis = self.gerenciador_cpfs.listar_cpfs_disponiveis()
            
            if not cpfs_disponiveis:
                custom_messagebox("info", "CPFs Disponíveis", 
                                "❌ Nenhum CPF disponível no momento.\n\n"
                                "Use o botão 'Obter CPF Criado' para gerar novos CPFs automaticamente.")
                return
            
            # Criar janela de seleção
            janela_cpfs = tk.Toplevel(self.janela_fornecedor)
            janela_cpfs.title("📋 CPFs Criados - Escolher da Lista")
            janela_cpfs.geometry("450x600")
            janela_cpfs.transient(self.janela_fornecedor)
            janela_cpfs.grab_set()
            
            # Centralizar janela
            janela_cpfs.update_idletasks()
            x = (janela_cpfs.winfo_screenwidth() // 2) - (225)
            y = (janela_cpfs.winfo_screenheight() // 2) - (300)
            janela_cpfs.geometry(f"450x600+{x}+{y}")
            
            frame = ttk.Frame(janela_cpfs, padding="15")
            frame.pack(fill='both', expand=True)
            
            # Cabeçalho
            header_frame = ttk.Frame(frame)
            header_frame.pack(fill='x', pady=(0, 15))
            
            ttk.Label(header_frame, text="📋 CPFs Criados Disponíveis", 
                    font=('Arial', 14, 'bold')).pack()
            ttk.Label(header_frame, text=f"Total disponível: {len(cpfs_disponiveis)}", 
                    font=('Arial', 10)).pack()
            
            # Lista de CPFs
            lista_frame = ttk.LabelFrame(frame, text="Selecione um CPF:")
            lista_frame.pack(fill='both', expand=True, pady=(0, 15))
            
            # Frame interno para Treeview e scrollbar
            tree_frame = ttk.Frame(lista_frame)
            tree_frame.pack(fill='both', expand=True, padx=10, pady=10)
            
            # Treeview para CPFs
            tree_cpfs = ttk.Treeview(tree_frame, columns=('CPF', 'Status'), show='headings', height=15)
            tree_cpfs.heading('CPF', text='CPF Disponível')
            tree_cpfs.heading('Status', text='Status')
            tree_cpfs.column('CPF', width=200, anchor='center')
            tree_cpfs.column('Status', width=100, anchor='center')
            
            # Scrollbar
            scroll_cpfs = ttk.Scrollbar(tree_frame, orient='vertical', command=tree_cpfs.yview)
            tree_cpfs.configure(yscrollcommand=scroll_cpfs.set)
            
            tree_cpfs.pack(side='left', fill='both', expand=True)
            scroll_cpfs.pack(side='right', fill='y')
            
            # Preencher lista
            for i, cpf in enumerate(cpfs_disponiveis, 1):
                cpf_formatado = f"{cpf[:3]}.{cpf[3:6]}.{cpf[6:9]}-{cpf[9:]}"
                tree_cpfs.insert('', 'end', values=(cpf_formatado, '✅ Disponível'), tags=(cpf,))
            
            def selecionar_cpf():
                selecionado = tree_cpfs.selection()
                if not selecionado:
                    custom_messagebox("warning", "Aviso", "⚠️ Selecione um CPF da lista")
                    return
                
                # Obter CPF selecionado (não formatado)
                cpf_selecionado = tree_cpfs.item(selecionado[0])['tags'][0]
                cpf_formatado = tree_cpfs.item(selecionado[0])['values'][0]
                
                # Preencher no formulário principal
                self.campos_form['cnpj_cpf'].delete(0, tk.END)
                self.campos_form['cnpj_cpf'].insert(0, cpf_formatado)
                
                # Configurar tipo como PF
                self.campos_form['tipo_pessoa'].set('PF')
                
                # Configurar PIX
                self.tipo_pix.set('CNPJ/CPF')
                self.campos_form['chave_pix'].delete(0, tk.END)
                self.campos_form['chave_pix'].insert(0, cpf_formatado)
                
                # Fechar janela
                janela_cpfs.destroy()
                
                # Focar no campo nome
                self.campos_form['razao_social'].focus()
                
                custom_messagebox("info", "CPF Selecionado", 
                                f"✅ CPF selecionado com sucesso!\n\n"
                                f"📋 {cpf_formatado}\n\n"
                                f"➡️ Continue preenchendo os dados")
            
            # Botões
            frame_botoes = ttk.Frame(frame)
            frame_botoes.pack(fill='x')
            
            ttk.Button(frame_botoes, text="✅ Selecionar", 
                    command=selecionar_cpf).pack(side='left', padx=5)
            ttk.Button(frame_botoes, text="❌ Cancelar", 
                    command=janela_cpfs.destroy).pack(side='left', padx=5)
            
            # Info adicional
            info_label = tk.Label(frame_botoes, 
                                text="💡 Dica: Dê duplo clique no CPF para selecioná-lo rapidamente",
                                font=('Arial', 8), fg='gray')
            info_label.pack(side='right', padx=10)
            
            # Double-click para selecionar rapidamente
            tree_cpfs.bind('<Double-1>', lambda e: selecionar_cpf())
            
        except Exception as e:
            custom_messagebox("error", "Erro", f"❌ Erro ao mostrar CPFs:\n{str(e)}")

    def usar_telefone_como_pix(self):
        """Usa o telefone digitado como chave PIX"""
        telefone = self.campos_form['telefone'].get().strip()
        
        if not telefone:
            custom_messagebox("warning", "Aviso", "⚠️ Digite o telefone primeiro!")
            self.campos_form['telefone'].focus()
            return
        
        # Limpar telefone (remover caracteres especiais)
        telefone_limpo = ''.join(filter(str.isdigit, telefone))
        
        # Verificar se tem pelo menos 10 dígitos
        if len(telefone_limpo) < 10:
            custom_messagebox("warning", "Aviso", "⚠️ Telefone deve ter pelo menos 10 dígitos!")
            self.campos_form['telefone'].focus()
            return
        
        # Formatar telefone para PIX
        if len(telefone_limpo) == 10:
            # Fixo: (XX) XXXX-XXXX
            tel_formatado = f"({telefone_limpo[:2]}) {telefone_limpo[2:6]}-{telefone_limpo[6:]}"
        elif len(telefone_limpo) == 11:
            # Celular: (XX) 9XXXX-XXXX
            tel_formatado = f"({telefone_limpo[:2]}) {telefone_limpo[2:7]}-{telefone_limpo[7:]}"
        else:
            # Manter como estava se tiver mais de 11 dígitos
            tel_formatado = telefone_limpo
        
        # Atualizar campo telefone com formatação
        self.campos_form['telefone'].delete(0, tk.END)
        self.campos_form['telefone'].insert(0, tel_formatado)
        
        # Definir tipo PIX como Telefone
        self.tipo_pix.set('Telefone')
        
        # Preencher chave PIX
        self.campos_form['chave_pix'].delete(0, tk.END)
        self.campos_form['chave_pix'].insert(0, tel_formatado)
        
        custom_messagebox("info", "PIX Configurado", 
                        f"✅ Telefone configurado como chave PIX!\n\n"
                        f"📱 {tel_formatado}\n\n"
                        f"➡️ Continue preenchendo os outros dados")

    def atualizar_chave_pix(self, event=None):
        """Atualiza o campo de chave PIX baseado no tipo selecionado"""
        tipo_selecionado = self.tipo_pix.get()
        self.campos_form['chave_pix'].delete(0, tk.END)
        
        if tipo_selecionado == 'CNPJ/CPF':
            self.campos_form['chave_pix'].insert(0, self.campos_form['cnpj_cpf'].get())
        elif tipo_selecionado == 'Telefone':
            self.campos_form['chave_pix'].insert(0, self.campos_form['telefone'].get())
        elif tipo_selecionado == 'Email':
            self.campos_form['chave_pix'].insert(0, self.campos_form['email'].get())
        
        # Atualizar resumo após alterar PIX
        self.atualizar_resumo_dados_bancarios()

    def atualizar_tipo_pessoa(self, event=None):
        """Determina automaticamente o tipo de pessoa baseado no CNPJ/CPF"""
        cnpj_cpf = self.campos_form['cnpj_cpf'].get().strip()
        # Remove caracteres não numéricos
        cnpj_cpf = ''.join(filter(str.isdigit, cnpj_cpf))
        
        if len(cnpj_cpf) <= 11:
            self.campos_form['tipo_pessoa'].set('PF')
        else:
            self.campos_form['tipo_pessoa'].set('PJ')

    def copiar_para_nome(self, event=None):
        """Copia a razão social para o nome se este estiver vazio"""
        razao_social = self.campos_form['razao_social'].get().strip()
        nome_atual = self.campos_form['nome'].get().strip()
        
        if razao_social and not nome_atual:
            self.campos_form['nome'].insert(0, razao_social)
 
    def validar_cnpj_cpf_numeros(self, numeros):
        """Valida CNPJ ou CPF usando apenas números"""
        if not numeros or not numeros.isdigit():
            return False
        
        if len(numeros) == 11:
            return self.validar_cpf_algoritmo(numeros)
        elif len(numeros) == 14:
            return self.validar_cnpj_algoritmo(numeros)
        else:
            return False

    def validar_cpf_algoritmo(self, cpf):
        """Valida CPF usando algoritmo oficial"""
        if cpf == cpf[0] * 11:
            return False
        
        # Calcular primeiro dígito verificador
        soma = 0
        for i in range(9):
            soma += int(cpf[i]) * (10 - i)
        
        resto = soma % 11
        digito1 = 0 if resto < 2 else 11 - resto
        
        if int(cpf[9]) != digito1:
            return False
        
        # Calcular segundo dígito verificador
        soma = 0
        for i in range(10):
            soma += int(cpf[i]) * (11 - i)
        
        resto = soma % 11
        digito2 = 0 if resto < 2 else 11 - resto
        
        return int(cpf[10]) == digito2

    def validar_cnpj_algoritmo(self, cnpj):
        """Valida CNPJ usando algoritmo oficial"""
        if cnpj == cnpj[0] * 14:
            return False
        
        # Calcular primeiro dígito verificador
        peso = [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]
        soma = sum(int(cnpj[i]) * peso[i] for i in range(12))
        resto = soma % 11
        digito1 = 0 if resto < 2 else 11 - resto
        
        if int(cnpj[12]) != digito1:
            return False
        
        # Calcular segundo dígito verificador
        peso = [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]
        soma = sum(int(cnpj[i]) * peso[i] for i in range(13))
        resto = soma % 11
        digito2 = 0 if resto < 2 else 11 - resto
        
        return int(cnpj[13]) == digito2

    def salvar_fornecedor(self):
        """Salva ou atualiza fornecedor — lê o formulário, valida e grava na planilha"""
        
        # ── 1. VALIDAÇÃO ──────────────────────────────────────────────
        campos_obrigatorios = ['tipo_pessoa', 'cnpj_cpf', 'razao_social', 'nome', 'categoria']
        for campo in campos_obrigatorios:
            if not self.campos_form[campo].get().strip():
                custom_messagebox("error", "Erro", f"❌ O campo {campo} é obrigatório!")
                return

        tipo_pessoa = self.campos_form['tipo_pessoa'].get()
        cnpj_cpf_numeros = ''.join(filter(str.isdigit, self.campos_form['cnpj_cpf'].get()))

        if not self.validar_cnpj_cpf_numeros(cnpj_cpf_numeros):
            custom_messagebox("error", "Erro",
                            f"❌ {'CPF' if tipo_pessoa == 'PF' else 'CNPJ'} inválido!")
            return

        # ── 2. MONTAR DADOS BANCÁRIOS ──────────────────────────────────
        chave_pix = self.campos_form['chave_pix'].get().strip()
        if chave_pix:
            dados_bancarios = f"PIX: {chave_pix}"
        else:
            partes = [self.campos_form[c].get().strip()
                    for c in ('banco', 'op', 'agencia', 'conta') 
                    if self.campos_form[c].get().strip()]
            dados_bancarios = ' - '.join(partes)

        # ── 3. DICIONÁRIO ÚNICO DE CAMPOS ─────────────────────────────
        #   Para adicionar um novo campo no futuro:
        #   a) inclua a entrada aqui
        #   b) adicione a coluna na planilha
        #   Só isso — nenhum outro lugar precisa ser alterado.
        dados = {
            'cnpj_cpf':      cnpj_cpf_numeros,
            'tipo_pessoa':   tipo_pessoa,
            'razao_social':  self.campos_form['razao_social'].get().upper(),
            'nome':          self.campos_form['nome'].get().upper(),
            'telefone':      self.campos_form['telefone'].get(),
            'email':         self.campos_form['email'].get(),
            'banco':         self.campos_form['banco'].get(),
            'op':            self.campos_form['op'].get(),
            'agencia':       self.campos_form['agencia'].get(),
            'conta':         self.campos_form['conta'].get(),
            'chave_pix':     chave_pix,
            'categoria':     self.campos_form['categoria'].get().upper(),
            'especificacao': self.campos_form['especificacao'].get().upper(),
            'vinculo':       self.campos_form['vinculo'].get().upper(),
            'dados_bancarios': dados_bancarios,
            'endereco':      self.campos_form['endereco'].get().upper(),
            'responsavel':   self.campos_form['responsavel'].get().upper(),
        }

        # ── 4. VERIFICAR CPF CRIADO (lógica preservada) ────────────────
        eh_cpf_criado = False
        if tipo_pessoa == 'PF':
            try:
                if not hasattr(self, 'gerenciador_cpfs'):
                    self.gerenciador_cpfs = GerenciadorCPFsCriados()
                if cnpj_cpf_numeros in self.gerenciador_cpfs.listar_cpfs_disponiveis():
                    eh_cpf_criado = True
            except Exception as e:
                logger.debug(f"Erro ao verificar CPF criado: {str(e)}")

        # ── 5. GRAVAR NA PLANILHA ──────────────────────────────────────
        try:
            from src.config.config import ARQUIVO_FORNECEDORES
            from openpyxl import load_workbook

            # Mapeamento colunas: (índice_zero_based → chave_do_dicionário)
            # Para adicionar coluna nova: acrescente a entrada aqui e no dicionário acima.
            COLUNAS = [
                'cnpj_cpf', 'tipo_pessoa', 'razao_social', 'nome',
                'telefone', 'email', 'banco', 'op', 'agencia', 'conta',
                'chave_pix', 'categoria', 'especificacao', 'vinculo',
                'dados_bancarios', 'endereco', 'status', 'responsavel',
            ]

            wb = load_workbook(ARQUIVO_FORNECEDORES)
            ws = wb['Fornecedores']

            # Garantir cabeçalho da coluna STATUS
            if ws.cell(1, 17).value != 'STATUS':
                ws.cell(1, 17, 'STATUS')

            # Ler todos os registros existentes
            fornecedores = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or not row[0]:
                    continue
                row_pad = list(row) + [None] * (len(COLUNAS) - len(row))
                reg = {col: (str(row_pad[i]).strip() if row_pad[i] else '')
                    for i, col in enumerate(COLUNAS)}
                reg['status'] = reg['status'].upper() if reg['status'] else 'ATIVO'
                if reg['cnpj_cpf'] and reg['nome']:
                    fornecedores.append(reg)

            # Inserir ou atualizar
            busca = ''.join(filter(str.isdigit, dados['cnpj_cpf']))
            encontrado = False
            for i, reg in enumerate(fornecedores):
                if ''.join(filter(str.isdigit, reg['cnpj_cpf'])) == busca:
                    dados['status'] = reg.get('status', 'ATIVO')  # preserva status
                    fornecedores[i] = dados.copy()
                    encontrado = True
                    break
            if not encontrado:
                dados['status'] = 'ATIVO'
                fornecedores.append(dados.copy())

            # Reescrever planilha ordenada
            fornecedores.sort(key=lambda x: x.get('nome', '').upper())
            max_row = ws.max_row
            if max_row > 1:
                ws.delete_rows(2, max_row - 1)

            for i, reg in enumerate(fornecedores, start=2):
                for j, col in enumerate(COLUNAS, start=1):
                    ws.cell(row=i, column=j, value=reg.get(col, ''))

            wb.save(ARQUIVO_FORNECEDORES)
            wb.close()

        except PermissionError:
            custom_messagebox("error", "Erro de Permissão",
                            "Arquivo aberto em outro programa! Feche o Excel e tente novamente.")
            return
        except Exception as e:
            logger.error(f"Erro ao salvar fornecedor: {str(e)}")
            custom_messagebox("error", "Erro", f"❌ Erro ao salvar:\n{str(e)}")
            return

        # ── 6. PÓS-SALVAMENTO ─────────────────────────────────────────
        if eh_cpf_criado:
            try:
                sucesso = self.gerenciador_cpfs.marcar_cpf_como_usado(
                    cnpj_cpf_numeros, dados['nome'])
                msg = ("✅ Fornecedor salvo!\n\n🔄 CPF criado marcado como usado."
                    if sucesso else
                    "✅ Fornecedor salvo!\n\n⚠️ Não foi possível marcar o CPF como usado.")
            except Exception as e:
                msg = "✅ Fornecedor salvo!"
        else:
            msg = "✅ Fornecedor salvo com sucesso!"

        custom_messagebox("info", "Sucesso", msg)
        self.janela_fornecedor.destroy()
        self.buscar_fornecedor()

